rng(2026);
N = 50;
P = randn(3, N);
P = P - mean(P, 2);   % 中心化

% 生成随机旋转 R0 (正交且 det = +1)
[Q0, R_qr] = qr(randn(3));
Q0 = Q0 * diag(sign(diag(R_qr)));
if det(Q0) < 0
    Q0(:, 3) = -Q0(:, 3);
end
R0 = Q0;

% 生成带噪目标点集并中心化
Q_pts = R0 * P + 0.01 * randn(3, N);
Q_pts = Q_pts - mean(Q_pts, 2);

% Kabsch 算法
M = P * Q_pts';
[U, ~, V] = svd(M);
D = diag([1, 1, sign(det(V * U'))]);
R = V * D * U';

rmsd = sqrt(mean(sum((R * P - Q_pts).^2, 1)));
fprintf('det(V*U'') = %+.1f, det(R) = %+.1f\n', det(V * U'), det(R));
fprintf('||R - R0||_F = %.6e, RMSD = %.6e\n', norm(R - R0, 'fro'), rmsd);

% 情形 2：对整个目标构象关于平面 z = 0 作镜像
Q_mirror_all = diag([1, 1, -1]) * Q_pts;
M_mir = P * Q_mirror_all';
[Um, ~, Vm] = svd(M_mir);
R_uncorrected = Vm * Um';
Dm = diag([1, 1, sign(det(R_uncorrected))]);
R_corrected = Vm * Dm * Um';

fprintf('\n整体镜像后：\n');
fprintf('未修正 det(V*U'') = %+.1f (得到反射而非旋转！)\n', det(R_uncorrected));
fprintf('修正后 det(R)     = %+.1f (最优真旋转)\n', det(R_corrected));
```

**分析说明**：
- 对带 $0.01$ 高斯噪声的 $50$ 个三维点集，Kabsch 算法以极高精度还原出原旋转矩阵：$\lVert\bm{R}-\bm{R}_0\rVert_F$ 与均方根偏差（RMSD）均约在 $10^{-3}\text{–}10^{-2}$ 量级。
- 若把目标点构象关于平面作镜像反射（例如手性分子或蛋白质的对映异构体），相关矩阵 $\bm{M}=\sum_k\boldsymbol p_k\boldsymbol q_k^\top$ 的行列式变为负值，此时若不作行列式修正，直接取 $\bm{R}=\bm{V}\bm{U}^\top$ 将得到 $\det(\bm{V}\bm{U}^\top)=-1$ 的瑕正交矩阵（即包含反射的镜像变换），在刚体运动中物理上不可实现；而若仅对海量点中的个别点作镜像（且其余绝大多数点仍符合手性），$\bm{V}\bm{U}^\top$ 仍会维持 $\det=+1$，但残差 RMSD 会在该离群点处明显增大。加上修正矩阵 $\operatorname{diag}(1,1,\operatorname{sgn}(\det(\bm{V}\bm{U}^\top)))$ 把 $\bm{U}$ 的最后一列反号后，即可保证输出始终落在旋转群（$\det\bm{R}=+1$）内并取得给定旋转方向下的最小二乘配准。
